// (e.g. "TEXT[]", "BIGINT[]", "INTEGER[]", "UUID[]", "_text", "_int8", "varchar[]").
func isPostgresArrayColumnType(dataType string) bool {
	dt := strings.ToLower(strings.TrimSpace(stripColTypeFlags(dataType)))
	if strings.Contains(dt, "[]") {
		return true
	}
	switch dt {
	case "_text", "_varchar", "_bpchar", "_int2", "_int4", "_int8", "_uuid", "_numeric", "_float4", "_float8", "_bool":
		return true
	}
	return false
}

// formatPostgresArrayLiteral converts a Go slice or JSON array string (`["a","b"]`)
// into a valid PostgreSQL array literal (`{"a","b"}` or `{1,2}`) to prevent SQLSTATE 22P02.
func formatPostgresArrayLiteral(v any) (string, bool) {
	switch arr := v.(type) {
	case []any:
		return formatPostgresArraySlice(arr), true
	case []string:
		elems := make([]any, len(arr))
		for i, s := range arr {
			elems[i] = s
		}
		return formatPostgresArraySlice(elems), true
	case []int64:
		elems := make([]any, len(arr))
		for i, n := range arr {
			elems[i] = n
		}
		return formatPostgresArraySlice(elems), true
	case []int:
		elems := make([]any, len(arr))
		for i, n := range arr {
			elems[i] = n
		}
		return formatPostgresArraySlice(elems), true
	case string:
		trimmed := strings.TrimSpace(arr)
		if strings.HasPrefix(trimmed, "{") && strings.HasSuffix(trimmed, "}") {
			return trimmed, true
		}
		if strings.HasPrefix(trimmed, "[") && strings.HasSuffix(trimmed, "]") {
			var parsed []any
			dec := json.NewDecoder(strings.NewReader(trimmed))
			dec.UseNumber()
			if err := dec.Decode(&parsed); err == nil {
				return formatPostgresArraySlice(parsed), true
			}
		}
	}
	return "", false
}

