		}
	}
	return result
}

func parseTypePresenceFields(sourceField string) []string {
	return ParseTypePresenceFields(sourceField)
}

// BuildTypePresenceSubset produces a flat map of {field -> bsonTypeString} for a given raw JSON document and list of fields.
func BuildTypePresenceSubset(rawStr string, fields []string) map[string]any {
	result := make(map[string]any, len(fields))
	for _, field := range fields {
		gres := gjson.Get(rawStr, field)
		if !gres.Exists() {
			gres = gjson.Get(rawStr, "after."+field)
		}
		if !gres.Exists() {
			continue
		}
		if gres.Type == gjson.Null {
			result[field] = "null"
			continue
		}
		val := gjsonValueToGo(gres)
		result[field] = detectBsonType(val)
	}
	return result
}

func buildTypePresenceSubset(rawStr string, fields []string) map[string]any {
	return BuildTypePresenceSubset(rawStr, fields)
}

