func buildTypePresenceSubset(rawStr string, fields []string) map[string]any {
	return BuildTypePresenceSubset(rawStr, fields)
}

func buildColTypesFromRules(rules []mappingRuleRow) map[string]string {
	colTypes := make(map[string]string, len(rules))
	for _, r := range rules {
		dt := strings.TrimSpace(r.DataType)
		if IsTypePresenceRule(r.SourceField) {
			colTypes[r.TargetColumn] = dt + " " + colTypeFlagTypePresence
		} else if IsJSONValueSubsetRule(r.SourceField) {
			colTypes[r.TargetColumn] = dt + " " + colTypeFlagValueSubset
		} else {
			colTypes[r.TargetColumn] = dt
		}
	}
	return colTypes
}

